#!/usr/bin/env python3
"""Build curriculum/misconceptions.json from a hand-curated list. Each entry is a confusion an examiner report states
candidates made, restated in our words (no report wording), tied to its best-fit objective, with a test that tells the two
ideas apart. Curation drops answering habits, practical mishaps, language slips, and anything where the board's own
statement looks doubtful (those go to the source-doubts register in the corpus analysis, not here).
Run from the repository root with plain python3."""
import json, re, datetime, collections
W = "work/nam-8223-nsscas-2026/"
ev = {r["evidence_id"]: r for r in json.load(open(W + "assessment-evidence/assessment_evidence.json"))["records"]}
obj = {o["objective_id"]: o for o in json.load(open(W + "curriculum/objective_ids.json"))["objectives"]}
for _a in json.load(open(W + "curriculum/annexe-objectives.json"))["objectives"]:
    obj[_a["objective_id"]] = {"leaf": _a["topic_id"], "text": _a["syllabus_text"]}
P = "EV-8223-"
NN, AC, WA = "near_neighbour_term", "adjacent_concept", "wrong_angle_same_concept"
# (objective, kind, error, correct idea, test, [evidence ids without prefix])
E = [
 ("1.1-05", NN, "Treating 'organism' and 'species' as the same thing when explaining the species concept", "A species is a group of organisms that share features (or can interbreed); an organism is one individual placed into a species", "Is it describing one individual, or the group that individual is placed in?", ["2024-P2-Q1b-i"]),
 ("1.1-05", NN, "Describing the morphological species concept as resting on biochemical or genetic features", "The morphological species concept groups organisms by shared observable structural features", "Could it be applied to a preserved specimen with only its shape to go on?", ["2024-P2-Q1b-ii"]),
 ("1.1-05", AC, "Choosing the biological species concept to classify fossils", "The biological species concept depends on interbreeding, which cannot be tested in fossils; the morphological concept uses structure and can be", "Can the organisms be observed breeding?", ["2025-P1-Q2"]),
 ("1.1-01", NN, "Swapping the two parts of a binomial name or not knowing which is the genus", "The first name is the genus (capital letter); the second is the species (lower case); closely related species share a genus", "Which word would two closely related species share?", ["2024-P2-Q1c-i"]),
 ("1.2-05", NN, "Using 'transect' and 'quadrat' as synonyms, and treating a transect as random sampling", "A quadrat is a frame marking out a sample area; a transect is a line along which samples are taken, placed deliberately to show change across a gradient", "Is the sampling position chosen along a line on purpose, or at random?", ["2024-P2-Q1a"]),
 ("1.2-02", AC, "Judging biodiversity by the total number of organisms, or by the number of species alone", "Biodiversity depends on how many species there are and how evenly individuals are spread between them (as well as habitat and genetic variation)", "Two samples each hold 100 individuals: one is 99 of one species plus 1 of another. Which is more diverse?", ["2024-P2-Q1d-i"]),
 ("1.2-04", WA, "Reading a Simpson's index value without knowing what high and low values mean", "A value of D closer to 1 means higher diversity: many species with individuals spread fairly evenly", "Does a high D mean a few dominant species, or many evenly spread species?", ["2025-P1-Q3"]),
 ("1.2-01", NN, "Confusing habitat with niche, or leaving feeding relationships out of a niche", "A habitat is where an organism lives; a niche is its role: the conditions it tolerates, the resources it uses and its feeding and other interactions with organisms", "Is it a place, or what the organism does and needs in that place?", ["2025-P1-Q4"]),
 ("1.2-06", WA, "Giving a population estimate as a fraction or decimal", "Individuals are counted in whole numbers, so an estimate is rounded to a whole number", "Can there be 36.5 beans in a bag?", ["2024-P3-Q1a-ii"]),
 ("1.2-06", NN, "Writing that animals 'feed on grazers and browsers' instead of being grazers or browsers", "Grazers feed mainly on grass; browsers feed on leaves and shoots of shrubs and trees; the word names the animal's feeding type, not its food", "Does the word name the animal or its food?", ["2024-P3-Q1c-i"]),
 ("1.2-06", AC, "Suggesting culling or contraception as a way to deal with an anomalous result in a data set", "An anomalous result is dealt with in the data (check, repeat, exclude and say so); culling or contraception manages animal populations in the field", "Is the action applied to the data or to the animals?", ["2024-P3-Q1c-ii"]),
 ("1.3-06", AC, "Choosing 'create more nature reserves' as the way to restore a habitat that is already degraded", "Reserves protect habitat that still exists; restoring degraded habitat needs active work on the damaged land, such as replanting and removing alien species", "Is the habitat still intact, or already damaged?", ["2024-P1-Q3"]),
 ("2.1-02", NN, "Confusing magnification with resolution, or saying the image has high resolution instead of the microscope", "Magnification is how many times larger the image is than the object; resolution is the smallest distance at which two points still appear separate, and it belongs to the microscope", "Does making an image bigger show any more detail?", ["2025-P1-Q5", "2024-P2-Q2a"]),
 ("2.1-01", AC, "Not knowing that a scanning electron microscope shows surface detail only", "A scanning electron microscope shows the surface in three dimensions; a transmission electron microscope shows the inside of a thin section", "Does the micrograph show a surface or an interior?", ["2024-P2-Q2a"]),
 ("4.2-04", WA, "Converting between millimetres and micrometres incorrectly, or not scaling an eyepiece division against the stage micrometer", "1 mm = 1000 micrometres; calibrate by comparing a count of eyepiece divisions with the matching stage micrometer reading, then find micrometres per division", "How many micrometres are 0.4 mm, and how many micrometres is one eyepiece division if 20 divisions match 0.2 mm?", ["2024-P3-Q2a-i", "2025-P1-Q6"]),
 ("2.1-05", WA, "Quoting only the eyepiece lens or only the objective lens as the magnification", "Total magnification is the eyepiece magnification multiplied by the objective magnification", "Eyepiece x10, objective x40: what is the total?", ["2021-P3-Q2a-i"]),
 ("2.2-01", NN, "Mixing up organelles, cells and organisms, for example calling microvilli or villi cells", "Organelles sit inside cells; cells build tissues and organisms; microvilli are folds of the cell surface membrane and villi are folds of the gut lining", "Is it a structure inside a cell, a whole cell, or a whole organism?", ["2021-P2-Q1d"]),
 ("2.2-01", NN, "Calling microvilli cilia", "Microvilli are small projections that increase surface area for absorption; cilia are longer and beat to move material", "Does it absorb, or does it move material along?", ["2024-P2-Q2c-iv"]),
 ("2.2-01", NN, "Swapping the Golgi apparatus and the endoplasmic reticulum", "Rough ER is a continuous network of flattened sacs studded with ribosomes; the Golgi is a stack of flattened sacs that pinches off vesicles", "Continuous network or stack with vesicles?", ["2024-P2-Q2c-ii"]),
 ("2.2-08", AC, "Giving 'animal cell' or 'bacterium', or a domain name, when asked for the two cell types", "The two cell types are eukaryotic (with membrane-bound organelles and a nucleus) and prokaryotic (without)", "Does the cell have a nucleus and membrane-bound organelles?", ["2024-P2-Q2c-iii"]),
 ("2.2-01", AC, "Putting the Golgi apparatus before protein synthesis in the route of a secreted protein", "The gene in the nucleus is copied to mRNA; ribosomes on rough ER make the protein; the Golgi then modifies and packages it", "Which structure makes the polypeptide, and which processes it afterwards?", ["2025-P1-Q8"]),
 ("2.2-01", NN, "Placing 70S ribosomes in the cytoplasm of eukaryotic cells", "Eukaryotic cytoplasm has 80S ribosomes; 70S ribosomes are in prokaryotes, mitochondria and chloroplasts", "Which cell or organelle holds 70S ribosomes?", ["2025-P1-Q9"]),
 ("4.2-06", NN, "Drawing individual cells in a plan diagram", "A plan diagram shows the outlines and layout of tissues only; individual cells are drawn in a high-power drawing", "Does the drawing show cell outlines, or only tissue regions?", ["2022-P3-Q2a-i", "2021-P3-Q2c-i"]),
 ("2.3.1-03", NN, "Giving cholesterol the job of the phospholipid heads", "Phospholipid heads are polar and face the water; cholesterol sits among the fatty acid tails and regulates membrane fluidity", "Which part faces water, and which sits among the tails?", ["2025-P1-Q11"]),
 ("2.3.1-01", NN, "Explaining the polar head of a phospholipid by the glycerol", "The head is polar because of the phosphate group; glycerol joins the head to the fatty acids", "Which part of the molecule carries the charge?", ["2022-P2-Q4a-ii"]),
 ("2.3.1-01", NN, "Calling the bilayer of a cell surface membrane a 'double membrane'", "A cell is bounded by one membrane made of a double layer of phospholipids; a double membrane is the envelope of an organelle such as the nucleus", "How many membranes bound the cell, and how many layers of phospholipid make it?", ["2025-P2-Q1a-i"]),
 ("2.3.1-04", AC, "Treating cell signalling as a nerve impulse or a reflex arc, or naming the signalling cell instead of the signalling molecule", "In cell signalling a chemical released by one cell binds to a receptor on a target cell and changes what it does; the signal is the molecule", "Is the signal a molecule binding a receptor, or an electrical impulse along a neurone?", ["2025-P2-Q1b-i", "2025-P2-Q1b-iii"]),
 ("2.3.2-03", WA, "Answering a surface-area-to-volume question about the size of the whole organism instead of the cell", "The ratio that matters is that of the cell, because substances cross the cell surface membrane", "Which surface do substances cross to reach a cell's contents?", ["2021-P2-Q1c"]),
 ("2.3.2-01", NN, "Naming diffusion or osmosis for bulk uptake into a cell, or confusing endosmosis with endocytosis", "Endocytosis takes in material in vesicles formed from the membrane and needs energy; osmosis is water movement down a water potential gradient", "Does the cell enclose the material in a vesicle, or does water simply move across?", ["2024-P2-Q2c-i"]),
 ("2.3.2-01", AC, "Saying cells differ in membrane thickness to explain how fast substances cross", "All cell surface membranes are the same phospholipid bilayer; the diffusion distance depends on cell size and layers of cells", "Does the membrane change, or the distance to travel?", ["2022-P2-Q1a", "2025-P2-Q1c-ii"]),
 ("5.1-02", WA, "Treating 1.6 x 10^-8 as larger than 1.6 x 10^-2", "A more negative power of ten is a smaller number", "Which is smaller, 1.6 x 10^-8 or 1.6 x 10^-2?", ["2025-P2-Q1c-i"]),
 ("2.3.2-03", AC, "Calling Paramecium a bacterium or virus, or giving it a cell wall", "Paramecium is a single-celled animal-like organism; animal-like cells have no cell wall", "Does an animal cell have a cell wall?", ["2025-P2-Q1c-ii"]),
 ("2.3.2-03", WA, "Saying an earthworm needs a circulatory system because it lives underground", "A large multicellular body needs a transport system because diffusion over its thickness is too slow, whatever the habitat", "Is the reason about habitat, or about how far substances must diffuse?", ["2025-P2-Q1c-ii"]),
 ("2.3.2-01", WA, "Claiming active transport from concentration data alone", "Active transport needs evidence of movement against the concentration gradient and of energy use, which concentration figures alone do not give", "What extra evidence would show energy is being used?", ["2021-P2-Q6a-i"]),
 ("2.4.1-02", NN, "Mixing up hydroxyl and carboxyl groups, or saying alpha and beta glucose differ in the number of rings", "Both isomers have one ring; they differ in whether the -OH on carbon 1 points below the ring (alpha) or above it (beta)", "Where is the -OH on carbon 1 in alpha glucose?", ["2021-P2-Q2a-ii"]),
 ("2.4.1-06", NN, "Saying hydrogen bonds join the glucose units into a cellulose chain", "Glycosidic bonds join the units; hydrogen bonds link neighbouring chains and make the fibre strong", "Which bond is within a chain and which is between chains?", ["2021-P2-Q2b-ii"]),
 ("2.4.1-09", AC, "Using a brown iodine result as evidence that sugar has formed", "Brown iodine shows only that starch is absent; the product, a reducing sugar, is shown by Benedict's test", "Is the evidence that starch has gone, or that sugar has appeared?", ["2024-P1-Q11"]),
 ("2.4.1-07", NN, "Linking ester bonds to carbohydrates", "Ester bonds join fatty acids to glycerol in triglycerides; glycosidic bonds join sugars", "Which bond joins sugars and which joins fatty acids to glycerol?", ["2025-P1-Q12"]),
 ("2.4.1-06", WA, "Explaining the strength of cellulose by solubility or pH effects", "Cellulose is strong because many hydrogen bonds hold parallel chains together in microfibrils", "What holds the chains together to resist stretching?", ["2025-P1-Q16"]),
 ("2.4.2-07", NN, "Describing hydrogen bonds as the bonds inside a water molecule", "The bonds inside a water molecule are covalent; hydrogen bonds form between the slightly positive hydrogen of one molecule and the slightly negative oxygen of another", "Is the bond within one molecule or between two?", ["2021-P2-Q2b-iii"]),
 ("2.4.2-04", WA, "Describing the red blood cell when asked about the haemoglobin molecule, or giving 'an ion' for the haem iron", "Haemoglobin has four polypeptide chains, each with one haem group holding one Fe2+ ion that binds one oxygen molecule", "How many haem groups does one haemoglobin molecule have?", ["2022-P2-Q1b"]),
 ("2.4.2-01", NN, "Calling the bond in a dipeptide a 'dipeptide bond'", "A dipeptide is two amino acids joined by a peptide bond formed by condensation between the carboxyl group of one and the amino group of the other", "What is the bond called, and which groups form it?", ["2024-P2-Q3a"]),
 ("2.4.2-02", AC, "Including R groups when explaining secondary structure", "Secondary structure comes from hydrogen bonds along the polypeptide backbone; R-group interactions belong to tertiary structure", "Do the R groups or the backbone form the hydrogen bonds of an alpha helix?", ["2025-P1-Q15"]),
 ("2.4.2-03", NN, "Confusing hydrogen bonds with disulfide bonds", "A disulfide bond is a strong covalent bond between sulfur atoms of two cysteines; hydrogen bonds are individually weak", "Which is a covalent bond, and between which atoms?", ["2025-P1-Q30"]),
 ("2.4.2-07", NN, "Mixing up cohesion and adhesion", "Cohesion is water molecules attracted to each other by hydrogen bonds; adhesion is water attracted to other surfaces such as cell walls", "Is the attraction between water molecules or between water and another surface?", ["2024-P1-Q19"]),
 ("2.4.2-06", NN, "Giving Benedict's or iodine tests when asked how to test for protein", "The biuret test is for protein; Benedict's is for reducing sugar and iodine is for starch", "Which test gives a violet colour with protein?", ["2021-P3-Q1f"]),
 ("2.5.2-01", AC, "Believing the reaction stops at the optimum temperature or pH", "At the optimum the enzyme works fastest; the rate falls on either side of it", "What happens to the rate just below and just above the optimum?", ["2025-P2-Q4a"]),
 ("2.5.1-03", AC, "Thinking enzymes are used up, or that substrate concentration rises as a reaction starts", "An enzyme is released unchanged and used again; substrate only falls as it is converted, while enzyme-substrate complexes stay at a steady level until substrate runs low", "What happens to the enzyme when the product leaves?", ["2025-P2-Q4c-i", "2025-P2-Q4c-ii"]),
 ("2.5.2-01", AC, "Saying any pH change denatures an enzyme", "Far from the optimum, the shape is lost permanently (denaturation); close to it, the active site changes shape reversibly and the rate falls", "Is the change permanent, and how far from the optimum is it?", ["2025-P2-Q4b-iii"]),
 ("2.5.2-01", AC, "Assuming a rise to 35 C denatures a human digestive enzyme", "35 C is below the optimum of about 37 C, so the rate increases; denaturation needs temperatures well above the optimum", "Is 35 C above or below this enzyme's optimum?", ["2022-P2-Q4b-iii"]),
 ("2.5.2-01", AC, "Thinking a higher temperature changes how much product the reaction finally makes", "The final amount of product depends on the amount of substrate; temperature changes only how fast it is reached", "What limits the total product: the temperature or the starting amount of substrate?", ["2022-P2-Q4b-iii"]),
 ("2.5.2-03", NN, "Not recognising that a lower maximum rate points to non-competitive inhibition", "Competitive inhibition can be overcome by more substrate so the same maximum rate is reached; non-competitive inhibition lowers the maximum rate", "Can adding more substrate restore the original maximum rate?", ["2025-P1-Q19"]),
 ("4.1-01", NN, "Not being able to say which variable is independent and which is dependent", "The independent variable is what the investigator changes; the dependent variable is what is measured", "Which variable do you set, and which do you record?", ["2022-P3-Q1c-i"]),
 ("4.4-09", NN, "Swapping accuracy and reliability", "Accuracy is closeness to the true value; reliability is getting consistent results when the work is repeated", "Is it about closeness to the true value, or agreement between repeats?", ["2022-P3-Q1c-iv"]),
 ("2.6.1-03", WA, "Explaining the xylem's structure as 'more space for flow', or saying the xylem is made of lignin or of dead cells", "Lignin is in the cell walls of xylem vessels; the vessels have no cytoplasm or organelles, so resistance to flow is low", "Is lignin in the walls or the contents, and what does the empty lumen do for flow?", ["2025-P2-Q3b"]),
 ("2.6.2-05", NN, "Mixing up the apoplast (cell walls) with the symplast (cytoplasm)", "The apoplast is the cell walls and spaces between cells; the symplast is the cytoplasm linked through plasmodesmata", "Which pathway runs through cell walls, and which through cytoplasm?", ["2025-P1-Q20", "2025-P2-Q3c-i"]),
 ("2.6.2-06", AC, "Assuming many epidermal layers is a feature every xerophyte has", "Xerophytes show different combinations of adaptations, such as thick cuticle, hairs, sunken stomata and rolled leaves", "Do all xerophytes share the same set of adaptations?", ["2025-P1-Q22"]),
 ("2.6.2-07", NN, "Writing 'translation' (or diffusion or active transport) for the movement of sucrose in the phloem", "Translocation is the transport of assimilates in phloem; translation is making a polypeptide at a ribosome", "Which word names sucrose transport in phloem?", ["2021-P2-Q6b-ii"]),
 ("2.6.2-08", WA, "Saying hydrogen ions bond with sucrose during loading", "Companion cells pump hydrogen ions out; the ions return through a co-transporter protein that brings sucrose in with them", "Which direction do hydrogen ions move through the co-transporter, and what comes with them?", ["2021-P2-Q6b-iii"]),
 ("2.6.2-02", WA, "Showing water movement without a direction, or in the wrong direction", "Water moves from a higher to a lower water potential, so toward the xylem", "From which region to which region does water move?", ["2025-P2-Q3c-i"]),
 ("2.7.1-04", WA, "Drawing or describing a neutrophil as having three nuclei", "A neutrophil has one nucleus with several lobes", "How many nuclei does a neutrophil have?", ["2021-P2-Q3a-i"]),
 ("2.7.1-10", NN, "Saying oxygen has an affinity for haemoglobin rather than haemoglobin having an affinity for oxygen", "Affinity describes how readily haemoglobin binds oxygen", "Which substance is described as having an affinity?", ["2022-P2-Q1c-i"]),
 ("2.7.1-12", AC, "Believing a lower pH means fewer hydrogen ions", "A lower pH means a higher hydrogen ion concentration, which lowers haemoglobin's affinity for oxygen (the Bohr shift)", "What happens to hydrogen ion concentration as pH falls?", ["2022-P2-Q1c-i"]),
 ("2.7.1-12", NN, "Confusing respiration with breathing, or saying oxygen is produced in respiration", "Breathing moves air in and out of the lungs; respiration releases energy from glucose in cells, using oxygen and producing carbon dioxide", "Is it gas movement at the lungs, or a reaction in cells?", ["2022-P2-Q1c-iii"]),
 ("2.7.1-09", NN, "Confusing hydrogencarbonate ions with carbon dioxide binding to haemoglobin", "Most carbon dioxide travels as hydrogencarbonate ions in plasma; a smaller share binds haemoglobin as carbaminohaemoglobin", "Which form carries most of the carbon dioxide?", ["2025-P1-Q25"]),
 ("2.7.1-03", NN, "Swapping the structures of arteries and veins", "Arteries have thick elastic and muscular walls and a narrow lumen; veins have thin walls, a wide lumen and valves", "Which has valves and a wide lumen?", ["2025-P3-Q2c"]),
 ("2.7.2-01", NN, "Confusing coronary arteries with the major vessels leaving the heart", "Coronary arteries branch from the aorta and supply the heart muscle itself", "Which vessels feed the heart's own muscle?", ["2025-P1-Q23"]),
 ("2.8.1-03", AC, "Describing malaria as passing directly from person to person, or as spread by droplets or contaminated water", "Malaria is transmitted by the female Anopheles mosquito, in which the parasite must develop before it can infect the next person", "What is the vector, and what must happen inside it?", ["2022-P2-Q2b", "2022-P2-Q2d-ii"]),
 ("2.8.1-04", AC, "Proposing measures that do not target the mosquito or the parasite, such as treating drinking water or blaming sewage for infection", "Control targets the mosquito's breeding sites and bites, and the parasite in people: nets, removing standing water, insecticides and antimalarial drugs", "Does the measure break the mosquito's life cycle or the parasite's spread?", ["2022-P2-Q2d-i"]),
 ("2.8.2-01", NN, "Calling Plasmodium a bacterium or a virus", "Plasmodium is a single-celled eukaryotic protoctist; penicillin acts on bacterial cell walls and not on it", "Is it a prokaryote, a virus or a eukaryote?", ["2022-P2-Q2e"]),
 ("2.8.2-01", WA, "Saying penicillin acts on the cell membrane as well as the wall", "Penicillin prevents bacteria building their cell walls so they burst; naming both wall and membrane gives a wrong answer", "Which structure does penicillin stop being built?", ["2022-P2-Q2e"]),
 ("2.8.2-02", NN, "Saying antibiotics become resistant, or that the patient becomes resistant", "Bacteria become resistant: a chance mutation lets some survive, and selection by the antibiotic makes them common", "What becomes resistant, and how?", ["2024-P2-Q2d"]),
 ("2.9.1-01", WA, "Saying a macrophage displays pieces of pathogen debris", "A macrophage places antigens from the pathogen on its own surface membrane to present to T cells", "What exactly sits on the macrophage's membrane?", ["2021-P2-Q3b-i"]),
 ("2.9.1-02", NN, "Treating antibodies as cells made by B-cell cloning", "B cells clone into plasma cells and memory cells; plasma cells secrete antibodies, which are proteins", "Which cell type makes antibodies, and what are antibodies?", ["2021-P2-Q3b-ii"]),
 ("2.10.1-07", AC, "Saying elastic fibres stop the alveoli collapsing", "Elastic fibres let the alveoli stretch when air enters and recoil to push air out", "What do the fibres do on inhaling and on exhaling?", ["2021-P2-Q4a-iii"]),
 ("2.10.1-06", NN, "Saying mucus sweeps dust out of the airway", "Mucus traps dust and microbes; the beating cilia move the mucus along", "Which one moves, and which one traps?", ["2025-P2-Q2a-ii"]),
 ("3.1.1-01", NN, "Confusing centromere with centrosome, and chromatin with chromosome", "The centromere holds sister chromatids together; centrosomes organise the spindle; chromatin is loose DNA with histones, and a chromosome is that DNA condensed", "Which holds chromatids together, and which makes the spindle?", ["2021-P2-Q5a"]),
 ("3.1.1-01", NN, "Labelling a sister chromatid as a telomere", "Telomeres are the DNA caps at the ends of each chromatid", "Is it the whole chromatid or the end of it?", ["2021-P2-Q5a"]),
 ("3.1.1-01", WA, "Counting one telomere per chromosome, or not realising a replicated chromosome has two chromatids with two telomeres each", "Each chromatid has a telomere at both ends, so a replicated chromosome has four", "How many telomeres does a metaphase chromosome have?", ["2025-P1-Q37"]),
 ("3.1.1-05", NN, "Describing a telomere as a plastic or hard cap", "A telomere is DNA made of repeated short sequences; because it is DNA, it takes part in replication", "What is a telomere made of?", ["2021-P2-Q5b"]),
 ("3.1.1-05", AC, "Saying a telomere stops the chromosome getting shorter", "The telomere itself loses a little at each replication; its loss protects the genes behind it", "Does the telomere shorten, and what does that protect?", ["2022-P2-Q3a-iv", "2021-P2-Q5b"]),
 ("3.1.1-07", NN, "Saying telomerase breaks telomeres down, speeds up mitosis or adds extra telomeres", "Telomerase replaces lost telomere DNA, so a cell avoids the shortening that leads to its death and can keep dividing", "Does telomerase add or remove telomere DNA?", ["2021-P2-Q5d"]),
 ("3.1.2-01", WA, "Saying chromosomes re-condense at the end of mitosis", "In telophase they decondense into chromatin; they condense again before the next division", "Do chromosomes condense or decondense in telophase?", ["2022-P2-Q3c"]),
 ("3.2.1-04", NN, "Confusing a DNA molecule with a strand in semi-conservative replication, or saying half a strand is conserved", "Each new molecule has one whole old strand and one whole new strand", "How many old strands are in each new molecule?", ["2022-P2-Q3d-ii"]),
 ("3.2.2-03", AC, "Describing replication or translation when asked about transcription, or saying mRNA is 'copied' DNA", "In transcription RNA nucleotides pair with the template strand and are joined to make mRNA, which is a complementary RNA, not a copy of the DNA", "Is the product DNA, RNA or protein, and what is it built from?", ["2024-P2-Q3b"]),
 ("3.2.2-06", NN, "Not distinguishing codon, anticodon and amino acid, or naming the wrong structure for where anticodons sit", "A codon is three bases on mRNA; its complementary anticodon is on tRNA; the amino acid is carried at the other end of the tRNA", "Which of the three sits on mRNA, which on tRNA, and which is carried?", ["2024-P2-Q3d-ii"]),
 ("3.2.2-02", WA, "Forgetting that each amino acid is coded by three nucleotides", "The code is a triplet: three bases code for one amino acid", "How many bases code for one amino acid?", ["2025-P1-Q38"]),
]
entries, per_unit = [], collections.Counter()
for o, kind, a, b, test, evs in E:
    assert o in {k.replace("OBJ-8223-", "") for k in obj}, o
    full = [P + e for e in evs]
    for f in full:
        assert f in ev, "missing evidence record " + f
    oid = "OBJ-8223-" + o; unit = obj[oid]["leaf"]; per_unit[unit] += 1
    series = sorted({ev[f]["year"] for f in full})
    entries.append({"evidence_scope": "topic", "entry_id": "MC-8223-%s-%02d" % (unit, per_unit[unit]), "topic_id": unit,
                    "objective_id": oid, "objective_text": obj[oid]["text"], "a": a, "b": b, "kind": kind, "test": test,
                    "n": len(full), "series": series, "evidence": full})
out = {"register_id": "MISCON-NAM-NSSCAS-8223", "generated_at": datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
       "authority": "NSSCAS Examiners Reports 2021, 2022, 2024 and 2025 (Biology 8223). 2023 has no report. Each entry is a confusion an examiner report states candidates made.",
       "derivation_policy": "Curated by hand from the located examiner statements (126 raw statements tagged as misconceptions, plus omissions) and restated in our words. No examiner-report wording appears in learner-facing output. Answering habits, practical mishaps, language slips, and statements where the board's own account looks doubtful were left out.",
       "how_to_use": "Every entry earns one MISCON card on its objective. A MISCON card is a DISCRIMINATION: the error, the correct idea, and the test that tells them apart (the test field). The correct idea (b) is our statement of standard biology consistent with the syllabus, not a board quotation; it needs the two-source verification in the plan before any card is published.",
       "kinds": {NN: "Two terms that share most of their wording or meaning.", AC: "Two different concepts that sit near each other in the syllabus.", WA: "The right concept answered from the wrong angle, or a step of it done wrongly."},
       "entries": entries}
json.dump(out, open(W + "curriculum/misconceptions.json", "w"), indent=1, ensure_ascii=False)
print("entries", len(entries)); print("per unit", dict(sorted(per_unit.items(), key=lambda x: [int(p) for p in x[0].split('.')])))
print("kinds", dict(collections.Counter(e["kind"] for e in entries)))
